import java.io.Serializable;
import java.util.ArrayList;
import java.util.Collections;
import java.util.List;

import com.vaadin.flow.server.VaadinSession;

/**
 * Keeps the messages that have been sent, so that they are still there when the
 * user leaves the contact view and comes back to it.
 * <p>
 * The messages live in the Vaadin session: nothing is written to disk, but they
 * outlive any single visit to the view.
 */
public class MessageStore implements Serializable {

    private final List<Message> messages = new ArrayList<>();

    /**
     * The store of the current session, created on first use.
     */
    public static MessageStore current() {
        VaadinSession session = VaadinSession.getCurrent();
        if (session == null) {
            // No session at all (should not happen in a view): a throw-away
            // store keeps the view working instead of failing to build.
            return new MessageStore();
        }
        MessageStore store = session.getAttribute(MessageStore.class);
        if (store == null) {
            store = new MessageStore();
            session.setAttribute(MessageStore.class, store);
        }
        return store;
    }

    /**
     * Adds a message as the newest one.
     */
    public void add(Message message) {
        messages.add(0, message);
    }

    /**
     * All messages sent so far, newest first.
     */
    public List<Message> newestFirst() {
        return Collections.unmodifiableList(new ArrayList<>(messages));
    }
}
