+import com.vaadin.flow.component.grid.Grid;
+import com.vaadin.flow.component.html.H1;
+import com.vaadin.flow.component.html.Paragraph;
+import com.vaadin.flow.component.notification.Notification;
+import com.vaadin.flow.component.orderedlayout.VerticalLayout;
+import com.vaadin.flow.component.textfield.EmailField;
+import com.vaadin.flow.component.textfield.TextArea;
+import com.vaadin.flow.component.textfield.TextField;
+import com.vaadin.flow.component.textfield.TextFieldBase;
+import com.vaadin.flow.data.value.ValueChangeMode;
+import com.vaadin.flow.router.BeforeLeaveEvent;
+import com.vaadin.flow.router.BeforeLeaveEvent.ContinueNavigationAction;
+import com.vaadin.flow.router.BeforeLeaveObserver;
+import com.vaadin.flow.router.PageTitle;
+import com.vaadin.flow.router.Route;
+import com.vaadin.flow.router.RouterLink;
+
+@Route("contact")
+@PageTitle("Contact")
+public class ContactView extends VerticalLayout implements BeforeLeaveObserver {
+
+    private static final int MAX_MESSAGE_LENGTH = 500;
+
+    private static final Pattern EMAIL_PATTERN = Pattern
+            .compile("^[A-Za-z0-9!#$%&'*+/=?^_`{|}~.-]+@[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?"
+                    + "(\\.[A-Za-z0-9]([A-Za-z0-9-]*[A-Za-z0-9])?)*\\.[A-Za-z]{2,}$");
+
+    private final TextField name = new TextField("Name");
+    private final EmailField email = new EmailField("Email");
+    private final TextField phone = new TextField("Phone");
+    private final TextArea message = new TextArea("Message");
+    private final Button send = new Button("Send");
+
+    private final Grid<Message> sentMessages = new Grid<>(Message.class, false);
+
+    private final MessageStore store = MessageStore.current();
+
+    private final Dialog leaveDialog = new Dialog();
+    private ContinueNavigationAction pendingNavigation;
+
+    /**
+     * True while the form is being emptied after a send, so that emptying it
+     * does not count as the user editing it.
+     */
+    private boolean clearingForm;
+
+    public ContactView() {
+        setSizeFull();
+
+        add(new H1("Contact"));
+        add(new RouterLink("About", AboutView.class));
+
+        prepare(name);
+        prepare(email);
+        prepare(phone);
+        prepare(message);
+
+        FormLayout form = new FormLayout(name, email, phone, message);
+        form.setResponsiveSteps(new ResponsiveStep("0", 1), new ResponsiveStep("40em", 2));
+        form.setColspan(message, 2);
+        add(form);
+
+        send.addClickListener(event -> trySend());
+        send.addClickShortcut(Key.ENTER);
+        add(send);
+
+        sentMessages.addColumn(Message::getName).setHeader("Name").setKey("name")
+                .setAutoWidth(true);
+        sentMessages.addColumn(Message::getMessage).setHeader("Message").setKey("message")
+                .setFlexGrow(1);
+        sentMessages.setAllRowsVisible(true);
+        refreshMessages();
+        add(sentMessages);
+
+        buildLeaveDialog();
+        addDetachListener(event -> leaveDialog.close());
+    }
+
+    /**
+     * The four inputs behave the same way: they report every keystroke to the
+     * server, and they never validate themselves — {@link #trySend()} decides
+     * what is wrong with them and says so.
+     */
+    private void prepare(TextFieldBase<?, String> field) {
+        field.setValueChangeMode(ValueChangeMode.EAGER);
+        field.setManualValidation(true);
+        field.setClearButtonVisible(true);
+        field.setWidthFull();
+        field.addValueChangeListener(event -> {
+            if (!clearingForm) {
+                send.setEnabled(true);
+            }
+        });
+    }
+
+    private void buildLeaveDialog() {
+        leaveDialog.setHeaderTitle("Discard your message?");
+        leaveDialog.add(new Paragraph(
+                "You have not sent your message yet. If you leave now, it is lost."));
+        leaveDialog.setCloseOnEsc(false);
+        leaveDialog.setCloseOnOutsideClick(false);
+
+        Button keepEditing = new Button("Keep editing", event -> {
+            leaveDialog.close();
+            pendingNavigation = null;
+            releaseBrowserNavigation();
+        });
+        Button discard = new Button("Discard", event -> {
+            leaveDialog.close();
+            ContinueNavigationAction action = pendingNavigation;
+            pendingNavigation = null;
+            if (action != null) {
+                action.proceed();
+            }
+        });
+        leaveDialog.getFooter().add(keepEditing, discard);
+    }
+
+    /**
+     * Tells the router in the browser that the navigation it is holding on to
+     * is off. A postponed navigation leaves the browser side waiting for an
+     * answer, and until it gets one it quietly swallows every later navigation
+     * — so without this, the About link would stop working after the user has
+     * chosen to keep editing once.
+     */
+    private void releaseBrowserNavigation() {
+        getUI().map(ui -> ui.getInternals().getWrapperElement())
+                .ifPresent(wrapper -> wrapper.executeJs(
+                        "if (this.serverConnected) { this.serverConnected(true); }"));
+    }
+
+    private void trySend() {
+        String nameValue = valueOf(name);
+        String emailValue = valueOf(email);
+        String phoneValue = valueOf(phone);
+        String messageValue = valueOf(message);
+
+        clearErrors();
+        boolean valid = true;
+
+        if (nameValue.isBlank()) {
+            markInvalid(name, "Name is required");
+            valid = false;
+        }
+
+        if (!emailValue.isBlank() && !isEmailAddress(emailValue.trim())) {
+            markInvalid(email, "Enter a valid e-mail address");
+            valid = false;
+        } else if (emailValue.isBlank() && phoneValue.isBlank()) {
+            markInvalid(email, "Give an e-mail address or a phone number");
+            valid = false;
+        }
+
+        if (messageValue.isBlank()) {
+            markInvalid(message, "Message is required");
+            valid = false;
+        } else if (messageValue.length() > MAX_MESSAGE_LENGTH) {
+            markInvalid(message, "Message must be at most " + MAX_MESSAGE_LENGTH + " characters");
+            valid = false;
+        }
+
+        if (!valid) {
+            // Nothing is sent, and what the user typed stays where it is.
+            return;
+        }
+
+        store.add(new Message(nameValue, emailValue, phoneValue, messageValue));
+        refreshMessages();
+        clearForm();
+        send.setEnabled(false);
+        Notification.show("Message sent");
+    }
+
+    private static boolean isEmailAddress(String value) {
+        return EMAIL_PATTERN.matcher(value).matches();
+    }
+
+    private void markInvalid(TextFieldBase<?, String> field, String errorMessage) {
+        field.setErrorMessage(errorMessage);
+        field.setInvalid(true);
+    }
+
+    private void clearErrors() {
+        for (TextFieldBase<?, String> field : fields()) {
+            field.setInvalid(false);
+            field.setErrorMessage(null);
+        }
+    }
+
+    private void clearForm() {
+        clearingForm = true;
+        try {
+            for (TextFieldBase<?, String> field : fields()) {
+                field.clear();
+            }
+        } finally {
+            clearingForm = false;
+        }
+    }
+
+    private void refreshMessages() {
+        sentMessages.setItems(store.newestFirst());
+    }
+
+    private List<TextFieldBase<?, String>> fields() {
+        return List.of(name, email, phone, message);
+    }
+
+    private static String valueOf(TextFieldBase<?, String> field) {
+        String value = field.getValue();
+        return value == null ? "" : value;
+    }
+
+    private boolean hasSomethingTyped() {
+        for (TextFieldBase<?, String> field : fields()) {
+            if (!valueOf(field).isEmpty()) {
+                return true;
+            }
+        }
+        return false;
+    }
+
+    @Override
+    public void beforeLeave(BeforeLeaveEvent event) {
+        if (!hasSomethingTyped()) {
+            // Nothing to lose, so do not get in the way.
+            return;
+        }
+        pendingNavigation = event.postpone();
+        leaveDialog.open();
+    }
+}
