+        PlaywrightAssertions.assertThat(page.locator("h1")).hasText(text);
+    }
+
+    private void waitForVaadin() {
+        page.waitForFunction(WAIT_FOR_VAADIN_SCRIPT);
+    }
+
+    private void fillValidForm() {
+        name().setValue("Ada");
+        email().setValue("ada@example.com");
+        message().setValue("Hello there");
+    }
+
+    @Test
+    void formStartsEmptyAndSendable() {
+        assertHeading("Contact");
+        assertEquals(1, aboutLink().count());
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+        send().assertEnabled();
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void emptyFormIsReportedFieldByField() {
+        send().click();
+        waitForVaadin();
+
+        name().assertInvalid();
+        name().assertErrorMessage("Name is required");
+        email().assertInvalid();
+        email().assertErrorMessage("Give an e-mail address or a phone number");
+        message().assertInvalid();
+        message().assertErrorMessage("Message is required");
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void invalidEmailIsReported() {
+        name().setValue("Ada");
+        email().setValue("not-an-address");
+        message().setValue("Hi");
+        send().click();
+        waitForVaadin();
+
+        email().assertInvalid();
+        email().assertErrorMessage("Enter a valid e-mail address");
+        name().assertValid();
+        email().assertValue("not-an-address");
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void tooLongMessageIsReported() {
+        name().setValue("Ada");
+        phone().setValue("123456");
+        message().setValue("x".repeat(501));
+        send().click();
+        waitForVaadin();
+
+        message().assertInvalid();
+        message().assertErrorMessage("Message must be at most 500 characters");
+        GridElement.get(page).assertRowCount(0);
+    }
+
+    @Test
+    void sendingShowsNotificationAndRow() {
+        fillValidForm();
+        send().click();
+        waitForVaadin();
+
+        assertTrue(new NotificationElement(page).getText().contains("Message sent"));
+
+        GridElement grid = GridElement.get(page);
+        grid.assertRowCount(1);
+        grid.assertCellContent(0, 0, "Ada");
+        grid.assertCellContent(0, 1, "Hello there");
+
+        name().assertValue("");
+        email().assertValue("");
+        phone().assertValue("");
+        message().assertValue("");
+
+        send().assertDisabled();
+        name().setValue("Grace");
+        waitForVaadin();
+        send().assertEnabled();
+    }
+
+    @Test
+    void enterSends() {
+        fillValidForm();
+        message().getInputLocator().press("Enter");
+        waitForVaadin();
+
+        GridElement.get(page).assertRowCount(1);
+        name().assertValue("");
+    }
+
+    @Test
+    void messagesSurviveLeavingTheView() {
+        fillValidForm();
+        send().click();
+        waitForVaadin();
+
+        aboutLink().click();
+        waitForVaadin();
+        assertHeading("About");
+
+        page.getByRole(AriaRole.LINK, new Page.GetByRoleOptions().setName("Contact")).click();
+        waitForVaadin();
+        GridElement.get(page).assertRowCount(1);
+    }
+
+    @Test
+    void leavingAnEmptyFormIsNotInterrupted() {
+        aboutLink().click();
+        waitForVaadin();
+
+        assertHeading("About");
+        assertFalse(new DialogElement(page).isVisible());
+    }
+
+    @Test
+    void leavingWithTypedTextAsksFirst() {
