+        assertHeading("Contact");
+        message().assertValue("Half written");
+
+        aboutLink().click();
+        waitForVaadin();
+        ButtonElement.getByText(page, "Discard").click();
+        waitForVaadin();
+        assertHeading("About");
+    }
