+
+        test(message()).setValue("x".repeat(500));
+        test(send()).click();
+        assertEquals(1, test(grid()).size());
+    }
+
+    @Test
+    void validForm_sendsClearsAndDisablesSend() {
+        navigate(ContactView.class);
