+        fillValidForm();
+        fireShortcut(Key.ENTER);
+
+        assertEquals(1, test(grid()).size());
+        assertEquals("", name().getValue());
+    }
+
+    @Test
+    void newestMessageComesFirst() {
+        navigate(ContactView.class);
+        test(name()).setValue("First");
+        test(phone()).setValue("123");
+        test(message()).setValue("one");
